<?php
// All records and requests are confined to the disposable native suite.
config(['mapa.company_uuid'=>$company,'mapa_mobile.caller_tracking_enabled'=>true]);
$journeyService=new App\MapaMobile\ConnectedTrackingService;
$journeyMobile=new App\MapaMobile\MobileService;
$ju=row('users',['company_uuid'=>$company,'email'=>'DEMO-journey@example.invalid','password'=>Illuminate\Support\Facades\Hash::make('DEMO-journey-only'),'email_verified_at'=>now(),'status'=>'active']);
row('company_users',['company_uuid'=>$company,'user_uuid'=>$ju,'status'=>'active']);
Illuminate\Support\Facades\DB::table('mapa_mobile_bindings')->insert(['id'=>(string)Illuminate\Support\Str::uuid(),'company_uuid'=>$company,'user_uuid'=>$ju,'role'=>'admin','enabled'=>true,'revision'=>1,'created_at'=>now(),'updated_at'=>now()]);
$ja=$journeyMobile->login(trackingRequest(['email'=>'DEMO-journey@example.invalid','password'=>'DEMO-journey-only']))['token'];
$jc=(string)Illuminate\Support\Str::uuid();
Illuminate\Support\Facades\DB::table('mapa_voice_calls')->insert(['id'=>$jc,'company_uuid'=>$company,'state'=>'needs_review','demo'=>false,'draft'=>json_encode(['callback_number'=>'+919000000001'])]);
$jissue=fn()=> $journeyService->issue(trackingRequest(['consent_to_message'=>true,'scope'=>'full_journey'],$ja),$jc);
$jl=$jissue();$jview=fn()=> $journeyService->view(trackingRequest([],$jl['token']));
check($jl['scope']==='full_journey'&&$jview()['stage']==='awaiting_assignment','journey awaits assignment');
check($jview()['caller_location_allowed']===true&&$jview()['ambulance']===null,'before assignment only caller can share');
check($jview()['contacts']===['driver'=>null,'caller'=>['name'=>'Callback number','phone'=>'+919000000001'],'hospital'=>null],'private journey has only bound callback before assignment');
$jpoint=Illuminate\Support\Facades\DB::raw("ST_GeomFromText('POINT(82.87 18.33)',0)");
$jp=row('places',['company_uuid'=>$company,'name'=>'DEMO confirmed pickup','location'=>$jpoint]);
$jd=row('places',['company_uuid'=>$company,'name'=>'DEMO hospital','location'=>$jpoint]);
$jpl=row('payloads',['company_uuid'=>$company,'pickup_uuid'=>$jp,'dropoff_uuid'=>$jd]);
$jv=row('vehicles',['company_uuid'=>$company,'plate_number'=>'DEMO-JOURNEY','online'=>false]);
$jo=row('orders',['company_uuid'=>$company,'payload_uuid'=>$jpl,'vehicle_assigned_uuid'=>$jv,'status'=>'dispatched','dispatched'=>true]);
Illuminate\Support\Facades\DB::table('mapa_voice_calls')->where('id',$jc)->update(['order_uuid'=>$jo,'state'=>'dispatched']);
$jpickup=$jview();
check($jpickup['planned_road_route']===null,'no road route is invented without fresh assigned ambulance GPS');
$journeyCandidate=['latitude'=>18.35,'longitude'=>82.89,'accuracy_m'=>7,'recorded_at'=>(int)round(microtime(true)*1000)];
$journeyService->location(trackingRequest(['consent'=>true,'confirm_pickup'=>true,...$journeyCandidate],$jl['token']));
check($jview()['caller_pickup_confirmation']['latitude']===18.35 && $jview()['pickup']['latitude']===18.33,'caller candidate does not move the accepted native trip pickup');
check($jpickup['stage']==='to_pickup'&&$jpickup['leg']==='pickup','caller pickup stage from native trip');
check($jpickup['pickup']['label']==='DEMO confirmed pickup'&&$jpickup['pickup']['latitude']===18.33,'confirmed pickup from native payload');
check($jpickup['destination']['label']==='DEMO hospital'&&$jpickup['ambulance']['location']===null,'destination genuine and unknown GPS stays unknown');
require __DIR__.'/trip-contacts-caller-native-cases.php';
check(Illuminate\Support\Facades\DB::table('mapa_tracking_links')->where('id',$jl['id'])->value('order_uuid')===$jo,'preassignment link bound to first native trip');
$jstaff=collect($journeyMobile->snapshot($journeyMobile->context(trackingRequest([],$ja)))['orders'])->firstWhere('id',Illuminate\Support\Facades\DB::table('orders')->where('uuid',$jo)->value('public_id'));
check($jstaff['tracking']['revision']===$jpickup['revision'],'staff and caller same projection revision');
require __DIR__.'/road-route-hook-native-cases.php';
Illuminate\Support\Facades\DB::table('orders')->where('uuid',$jo)->update(['status'=>'enroute']);
$jhospital=$jview();
check($jhospital['stage']==='to_hospital'&&$jhospital['leg']==='hospital'&&$jhospital['caller_location_allowed']===false,'hospital leg stops caller collection');
check($jhospital['caller_pickup_confirmation']===null,'pickup completion invalidates the projected caller candidate');
denied(fn()=> $journeyService->location(trackingRequest(['consent'=>true,'confirm_pickup'=>true,...$journeyCandidate],$jl['token'])),409);
check($jhospital['ambulance']['registration']==='DEMO-JOURNEY'&&$jhospital['eta']===null,'hospital leg keeps assigned ambulance without invented ETA');
denied(fn()=> $journeyService->location(trackingRequest(['consent'=>true,'latitude'=>18.33,'longitude'=>82.87,'accuracy_m'=>5,'recorded_at'=>(int)(microtime(true)*1000)],$jl['token'])),409);
$jd2=row('places',['company_uuid'=>$company,'name'=>'DEMO changed hospital','location'=>$jpoint]);
Illuminate\Support\Facades\DB::table('payloads')->where('uuid',$jpl)->update(['dropoff_uuid'=>$jd2]);
check($jview()['destination']['label']==='DEMO changed hospital'&&$jview()['revision']!==$jhospital['revision'],'changed destination synchronizes to caller');
Illuminate\Support\Facades\DB::table('places')->where('uuid',$jd2)->update(['company_uuid'=>$foreign]);
check($jview()['destination']===null,'foreign destination withheld');
Illuminate\Support\Facades\DB::table('places')->where('uuid',$jd2)->update(['company_uuid'=>$company]);
Illuminate\Support\Facades\DB::table('mapa_voice_calls')->where('id',$jc)->update(['draft'=>json_encode(['callback_number'=>'+919000000002'])]);
denied(fn()=> $jview(),410);
Illuminate\Support\Facades\DB::table('mapa_voice_calls')->where('id',$jc)->update(['draft'=>json_encode(['callback_number'=>'+919000000001'])]);
$jo2=row('orders',['company_uuid'=>$company,'status'=>'dispatched','dispatched'=>true]);
Illuminate\Support\Facades\DB::table('mapa_voice_calls')->where('id',$jc)->update(['order_uuid'=>$jo2]);
denied(fn()=> $jview(),410);
Illuminate\Support\Facades\DB::table('mapa_voice_calls')->where('id',$jc)->update(['order_uuid'=>$jo]);
Illuminate\Support\Facades\DB::table('orders')->where('uuid',$jo)->update(['status'=>'completed']);
denied(fn()=> $jview(),410);
check(App\MapaMobile\TripTrackingView::forOrder($jo,$company)['ambulance']===null,'completed projection removes ambulance');
Illuminate\Support\Facades\DB::table('orders')->where('uuid',$jo)->update(['status'=>'enroute']);
$old=$journeyService->issue(trackingRequest(['consent_to_message'=>true,'replace_existing'=>true],$ja),$jc);
$oldView=$journeyService->view(trackingRequest([],$old['token']));
check($oldView['status']==='pickup_complete'&&$oldView['ambulance']===null&&!isset($oldView['destination'],$oldView['stage']),'legacy pickup link is never widened');
check(!array_key_exists('contacts',$oldView),'legacy pickup capability gains no phone access');
denied(fn()=> $jview(),410);
echo "$count native integration checks passed; shared journey scope and synchronization verified.\n";
